function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 365;
  const pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  const esVenta = function (e) { return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad"; };
  const conteo = {};
  for (let i = 0; i < pedidos.length; i++) {
    const p = pedidos[i];
    if (!p || !p.creado || !esVenta(p.estado)) continue;
    const d = dia(p.creado);
    conteo[d] = (conteo[d] || 0) + 1;
  }
  const serie = [];
  const base = Date.parse(datos.hoy);
  for (let n = N - 1; n >= 0; n--) {
    const etiqueta = dia(new Date(base - n * 86400000).toISOString());
    serie.push({ etiqueta: etiqueta, valor: conteo[etiqueta] || 0 });
  }
  let total = 0;
  for (let k = 0; k < serie.length; k++) total += serie[k].valor;
  return {
    valor: total,
    unidad: "pedidos",
    serie: serie,
    nota: "Cuenta pedidos confirmados, enviados, entregados y con novedad por día de creación en Bogotá en los últimos 365 días."
  };
}

