function consultar(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const fmtBogota = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " ");
  const N = 7;
  const limite = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  const pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  const clientes = (datos.tablas && datos.tablas.clientes) || [];
  const nombrePorCliente = {};
  for (const c of clientes) {
    nombrePorCliente[c.id] = c.nombre;
  }
  const filas = [];
  for (const p of pedidos) {
    if (p.estado !== "novedad") continue;
    if (!p.creado) continue;
    const d = dia(p.creado);
    if (!(d > limite)) continue;
    filas.push({
      numero: p.numero,
      fecha: fmtBogota(p.creado),
      cliente: nombrePorCliente[p.clienteId] || p.clienteId || null,
      ciudad: p.ciudad || null,
      total: p.total,
      estado: p.estado
    });
  }
  filas.sort(function (a, b) {
    if (a.fecha < b.fecha) return 1;
    if (a.fecha > b.fecha) return -1;
    return b.numero - a.numero;
  });
  return filas.slice(0, 200);
}

