function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  var N = 60;
  var hoyDia = dia(datos.hoy);
  var corte = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p || !p.creado || !p.clienteId) continue;
    var e = p.estado;
    if (!(e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad")) continue;
    var d = dia(p.creado);
    if (!(d > corte && d <= hoyDia)) continue;
    conteo[p.clienteId] = (conteo[p.clienteId] || 0) + 1;
  }
  var total = 0;
  var repetidos = 0;
  for (var k in conteo) {
    if (!Object.prototype.hasOwnProperty.call(conteo, k)) continue;
    total += 1;
    if (conteo[k] > 1) repetidos += 1;
  }
  var valor = 0;
  if (total > 0) valor = Math.round((repetidos / total * 100) * 10) / 10;
  return {
    valor: valor,
    unidad: "%",
    nota: "Porcentaje de compradores con mas de una venta (confirmado, enviado, entregado o novedad) en los ultimos 60 dias sobre el total de compradores del periodo."
  };
}

