function calcular(datos) {
  function esVenta(e) {
    return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  }
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var productos = tablas.productos || [];
  var nombrePorId = {};
  for (var k = 0; k < productos.length; k++) {
    var pr = productos[k];
    if (pr && pr.id) nombrePorId[pr.id] = pr.nombre || pr.id;
  }
  var acum = {};
  var etiquetaDe = {};
  for (var i = 0; i < pedidos.length; i++) {
    var ped = pedidos[i];
    if (!ped || !esVenta(ped.estado)) continue;
    var items = ped.items || [];
    for (var j = 0; j < items.length; j++) {
      var it = items[j];
      if (!it) continue;
      var cant = Number(it.cantidad) || 0;
      if (cant <= 0) continue;
      var clave;
      var etiqueta;
      if (it.productoId) {
        clave = "id:" + it.productoId;
        etiqueta = nombrePorId[it.productoId] || it.nombre || it.productoId;
      } else {
        etiqueta = it.nombre || "Sin nombre";
        clave = "nombre:" + etiqueta;
      }
      if (!acum[clave]) { acum[clave] = 0; etiquetaDe[clave] = etiqueta; }
      acum[clave] += cant;
      if (it.productoId && etiquetaDe[clave] === it.productoId && it.nombre) etiquetaDe[clave] = it.nombre;
      if (it.productoId && nombrePorId[it.productoId]) etiquetaDe[clave] = nombrePorId[it.productoId];
    }
  }
  var serie = [];
  for (var key in acum) {
    if (Object.prototype.hasOwnProperty.call(acum, key)) {
      serie.push({ etiqueta: etiquetaDe[key], valor: acum[key] });
    }
  }
  serie.sort(function (a, b) {
    if (b.valor !== a.valor) return b.valor - a.valor;
    if (a.etiqueta < b.etiqueta) return -1;
    if (a.etiqueta > b.etiqueta) return 1;
    return 0;
  });
  var total = 0;
