function consultar(datos) {
  var dia = function (iso) {
    return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  };
  var N = 30;
  var hoyDia = dia(datos.hoy);
  var limiteDia = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var mensajes = (datos.tablas && datos.tablas.mensajes) ? datos.tablas.mensajes : [];
  var grupos = {};
  var i;
  for (i = 0; i < mensajes.length; i++) {
    var m = mensajes[i];
    if (!m || !m.creado || !m.clienteId) continue;
    var d = dia(m.creado);
    if (d <= limiteDia || d > hoyDia) continue;
    var k = m.clienteId + "|" + d;
    if (!grupos[k]) grupos[k] = [];
    grupos[k].push(m);
  }
  var tiempos = [];
  for (var key in grupos) {
    var arr = grupos[key];
    var primerCliente = null;
    var q;
    for (q = 0; q < arr.length; q++) {
      if (arr[q].rol === "cliente") {
        var t = Date.parse(arr[q].creado);
        if (primerCliente === null || t < primerCliente) primerCliente = t;
      }
    }
    if (primerCliente === null) continue;
    var primeraRespuesta = null;
    for (q = 0; q < arr.length; q++) {
      if (arr[q].rol === "agente") {
        var ta = Date.parse(arr[q].creado);
        if (ta > primerCliente && (primeraRespuesta === null || ta < primeraRespuesta)) primeraRespuesta = ta;
      }
    }
    if (primeraRespuesta === null) continue;
    var diffSeg = (primeraRespuesta - primerCliente) / 1000;
    if (diffSeg >= 0) tiempos.push(diffSeg);
  }
  tiempos.sort(function (a, b) { return a - b; });
  var n = tiempos.length;
  var mediana = null;
  var p90 = null;
  if (n > 0) {
    var med;
    if (n % 2 === 1) {
      med = tiempos[(n - 1) / 2];
    } else {
      med = (tiempos[n / 2 - 1] + tiempos[n / 2]) / 2;
    }
    mediana = Math.round(med);
    var idx = Math.ceil(0.9 * n) - 1;
    if (idx < 0) idx = 0;
    if (idx >= n) idx = n - 1;
    p90 = Math.round(tiempos[idx]);
  }
  return [{
    ventana_dias: N,
    conversaciones_con_respuesta: n,
    mediana_segundos: mediana,
    p90_segundos: p90
  }];
}

