  return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
}
function calcular(datos) {
  var N = 365;
  var tablas = datos.tablas || {};
  var clientes = tablas.clientes || [];
  var hoyMs = Date.parse(datos.hoy);
  var limite = diaBogota(new Date(hoyMs - N * 86400000).toISOString());
  var meses = [];
  var visto = {};
  for (var n = N - 1; n >= 0; n--) {
    var d = diaBogota(new Date(hoyMs - n * 86400000).toISOString());
    var m = d.slice(0, 7);
    if (!visto[m]) {
      visto[m] = true;
      meses.push(m);
    }
  }
  var conteo = {};
  var total = 0;
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (!c || !c.creado) continue;
    var dc = diaBogota(c.creado);
    if (dc > limite) {
      var mc = dc.slice(0, 7);
      conteo[mc] = (conteo[mc] || 0) + 1;
      total += 1;
    }
  }
  var serie = [];
  for (var j = 0; j < meses.length; j++) {
    var mm = meses[j];
    serie.push({ etiqueta: mm, valor: conteo[mm] || 0 });
  }
  return {
    valor: total,
    unidad: "clientes",
    serie: serie,
    nota: "Cuenta clientes nuevos por mes segun fecha de creacion en hora de Bogota en los ultimos 365 dias, hoy incluido."
  };
}

