function consultar(datos) {
  var tablas = datos.tablas || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var nombres = {};
  for (var i = 0; i < clientes.length; i++) {
    nombres[clientes[i].id] = clientes[i].nombre || "Sin nombre";
  }
  function fmtBogota(iso) {
    var d = new Date(Date.parse(iso) - 5 * 3600 * 1000);
    var s = d.toISOString();
    return s.slice(0, 10) + " " + s.slice(11, 16);
  }
  var hoyMs = Date.parse(datos.hoy);
  var LIMITE_MS = 3 * 86400000;
  var tmp = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "pendiente" || !p.creado) continue;
    var ms = Date.parse(p.creado);
    if (isNaN(ms)) continue;
    var diff = hoyMs - ms;
    if (!(diff > LIMITE_MS)) continue;
    var dias = Math.floor(diff / 86400000);
    tmp.push({
      numero: p.numero,
      cliente: nombres[p.clienteId] || "Sin nombre",
      ciudad: p.ciudad || "",
      total: typeof p.total === "number" ? p.total : 0,
      creado: fmtBogota(p.creado),
      dias_espera: dias,
      _ms: ms
    });
  }
  tmp.sort(function (a, b) { return b._ms - a._ms; });
  var filas = [];
  var n = tmp.length > 200 ? 200 : tmp.length;
  for (var k = 0; k < n; k++) {
    filas.push({
      numero: tmp[k].numero,
      cliente: tmp[k].cliente,
      ciudad: tmp[k].ciudad,
      total: tmp[k].total,
      creado: tmp[k].creado,
      dias_espera: tmp[k].dias_espera
    });
  }
  return filas;
}

